problems.solutionCode:
export type ServiceEdge = readonly [string, string];

function buildAdjacency(edges: readonly ServiceEdge[]): Map<string, string[]> {
  const adjacency = new Map<string, string[]>();
  for (const [fromService, toService] of edges) {
    if (!adjacency.has(fromService)) {
      adjacency.set(fromService, []);
    }
    if (!adjacency.has(toService)) {
      adjacency.set(toService, []);
    }
    adjacency.get(fromService)?.push(toService);
  }
  return adjacency;
}

function reconstructPath(
  parents: ReadonlyMap<string, string>,
  startService: string,
  targetService: string,
): string[] {
  const reversed: string[] = [targetService];
  let cursor: string | undefined = targetService;
  while (cursor !== undefined && cursor !== startService) {
    cursor = parents.get(cursor);
    if (cursor !== undefined) {
      reversed.push(cursor);
    }
  }
  return reversed.reverse();
}

function searchShortestParents(
  adjacency: ReadonlyMap<string, readonly string[]>,
  startService: string,
  targetService: string,
): Map<string, string> | null {
  const visited = new Set<string>([startService]);
  const parents = new Map<string, string>();
  const queue: string[] = [startService];
  for (let head = 0; head < queue.length; head += 1) {
    const current = queue[head];
    for (const neighbor of adjacency.get(current) ?? []) {
      if (visited.has(neighbor)) {
        continue;
      }
      visited.add(neighbor);
      parents.set(neighbor, current);
      if (neighbor === targetService) {
        return parents;
      }
      queue.push(neighbor);
    }
  }
  return null;
}

export function findShortestHopPath(
  edges: readonly ServiceEdge[],
  startService: string,
  targetService: string,
): string[] | null {
  const adjacency = buildAdjacency(edges);
  if (!adjacency.has(startService) || !adjacency.has(targetService)) {
    return null;
  }
  if (startService === targetService) {
    return [startService];
  }
  const parents = searchShortestParents(adjacency, startService, targetService);
  return parents === null ? null : reconstructPath(parents, startService, targetService);
}

