export type DependencyEdge = readonly [string, string];

type VisitState = "unvisited" | "visiting" | "visited";

function buildDependencyMap(
  packages: readonly string[],
  dependencies: readonly DependencyEdge[],
): Map<string, string[]> {
  const graph = new Map<string, string[]>();
  for (const pkg of packages) {
    graph.set(pkg, []);
  }
  for (const [pkg, dep] of dependencies) {
    const list = graph.get(pkg) ?? [];
    list.push(dep);
    graph.set(pkg, list);
  }
  return graph;
}

export function hasDependencyCycle(
  packages: readonly string[],
  dependencies: readonly DependencyEdge[],
): boolean {
  const graph = buildDependencyMap(packages, dependencies);
  const state = new Map<string, VisitState>();

  function explore(current: string): boolean {
    state.set(current, "visiting");
    for (const next of graph.get(current) ?? []) {
      const nextState = state.get(next) ?? "unvisited";
      if (nextState === "visiting") {
        return true;
      }
      if (nextState === "unvisited" && explore(next)) {
        return true;
      }
    }
    state.set(current, "visited");
    return false;
  }

  for (const pkg of graph.keys()) {
    const pkgState = state.get(pkg) ?? "unvisited";
    if (pkgState === "unvisited" && explore(pkg)) {
      return true;
    }
  }
  return false;
}

