export function collectImpactedPackages(
  dependentsMap: ReadonlyMap<string, readonly string[]>,
  rootPackage: string,
): string[] {
  const visited = new Set<string>([rootPackage]);
  const queue: string[] = [rootPackage];
  const impacted: string[] = [];
  while (queue.length > 0) {
    const current = queue.shift();
    if (current === undefined) {
      continue;
    }
    impacted.push(current);
    for (const next of dependentsMap.get(current) ?? []) {
      if (!visited.has(next)) {
        visited.add(next);
        queue.push(next);
      }
    }
  }
  return impacted;
}

