problems.solutionCode:
export type StationLink = readonly [string, string];

function buildUndirectedGraph(links: readonly StationLink[]): Map<string, string[]> {
  const graph = new Map<string, string[]>();
  for (const [stationA, stationB] of links) {
    if (!graph.has(stationA)) { graph.set(stationA, []); }
    if (!graph.has(stationB)) { graph.set(stationB, []); }
    graph.get(stationA)?.push(stationB);
    graph.get(stationB)?.push(stationA);
  }
  return graph;
}

export function computeHopDistances(
  links: readonly StationLink[],
  origin: string,
): Map<string, number> {
  const graph = buildUndirectedGraph(links);
  const distances = new Map<string, number>();
  if (!graph.has(origin)) {
    return distances;
  }
  distances.set(origin, 0);
  const queue: string[] = [origin];
  for (let head = 0; head < queue.length; head += 1) {
    const current = queue[head];
    const nextDist = (distances.get(current) ?? 0) + 1;
    for (const neighbor of graph.get(current) ?? []) {
      if (!distances.has(neighbor)) {
        distances.set(neighbor, nextDist);
        queue.push(neighbor);
      }
    }
  }
  return distances;
}

